#include "frontend_hud.hpp"
#include "ui_ttf.hpp"
#include <iostream>
#include <stdexcept>
using namespace ofo;
int main(int argc,char**argv){try{if(argc<2)return 0;Resources resources(argv[1]);FrontendHud hud(resources);int cases=0;for(auto dim:{std::pair<int,int>{640,480},{1280,720},{1920,1080},{2560,1080},{720,1280}})for(int mode=0;mode<5;++mode){RaceOverlayState s;s.elapsed=1234.567;s.lap_time=321.456;s.lap=3;s.laps=10;s.participants=8;s.position=7;s.show_positions=true;s.battle=mode==1;s.finished=mode==2;s.replay=mode==3;s.stunt.kind=mode==4?StuntKind::Longjump:StuntKind::None;s.event_intro=mode==4;s.event_hint=event_intro_hint(resources,RaceMode::Stunt,s.stunt.kind,s.language);s.finish_prompt="ENTER / A: GARAGE   P / F3: REPLAY";s.result_detail="RACE AWARD $10000   CAREER COMPLETE";for(int n=0;n<8;++n){RaceOverlayEntry e;e.name="A very long driver name for overflow verification";e.car_name="A very long car model name";e.rank=n+1;e.time=1234.567;e.finished=true;e.player=n==0;e.status="A very long custom race status";s.leaderboard.push_back(e);}auto commands=hud.commands(dim.first,dim.second,s);for(auto&c:commands)if(c.kind==FrontendDraw::Text){float w=ui_text_width_pixels(ui_raster_pixels(c.scale,c.heading),c.heading,c.value);if(w>c.w+.1f||c.x<-.1f||c.y<-.1f||c.x+w>dim.first+.1f||c.y+c.h>dim.second+.1f)throw std::runtime_error("HUD text overflow: "+c.value);}++cases;}std::cout<<"HUD 25 mode/resolution cases: actual glyph bounds and long driver/model/status slots pass\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
